class TradingEnv:
    def reset(self):
        self.position = 0
        self.cash = 100_000
        return self._get_state()

    def step(self, action):
        # action: -1 (sell), 0 (hold), 1 (buy)
        reward = self._compute_risk_adjusted_pnl(action)
        self.position += action
        return self._get_state(), reward, self._done(), {}

    def _get_state(self):
        return np.concatenate([self.market_features, [self.position, self.cash]])
